interface.definition:
#"SYSTEM_SYSRULES_headerContentLayout"(
  header: #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_sideBySideLayout"(
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_stampField"(
                      labelPosition: "COLLAPSED",
                      icon: "fingerprint",
                      marginAbove: "NONE",
                      align: "START"
                    ),
                    width: "MINIMIZE"
                  ),
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: {
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: "Ciudadanos",
                          size: "LARGE",
                          color: "#FFFFFF",
                          style: "STRONG"
                        )
                      },
                      marginAbove: "MORE",
                      marginBelow: "MORE",
                      align: "LEFT",
                      preventWrapping: true
                    )
                  )
                },
                alignVertical: "MIDDLE"
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(contents: {}, width: "NARROW"),
          #"SYSTEM_SYSRULES_columnLayout"(contents: {}, width: "NARROW"),
          #"SYSTEM_SYSRULES_columnLayout"(contents: {}, width: "NARROW")
        },
        alignVertical: "MIDDLE"
      )
    },
    style: "#063853",
    showBorder: false,
    padding: "LESS"
  ),
  contents: {
    #"SYSTEM_SYSRULES_gridField_v5"(
      label: "Tabla de solo lectura",
      labelPosition: "COLLAPSED",
      data: #"SYSTEM_SYSRULES_queryEntity_v2"(
        entity: #"_a-0000ef02-3502-8000-9bf1-011c48011c48_1558111",
        query: #"SYSTEM_SYSRULES_query"(
          pagingInfo: fv!pagingInfo
        ),
        fetchTotalCount: true
      ),
      columns: {
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Correo Electronico",
          value: a!defaultValue(fv!row.CorreoElectronico, "–"),
          sortField: "CorreoElectronico",
          align: "CENTER",
          width: "4X"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Nombre",
          value: a!defaultValue(fv!row.RazonSocial, "–"),
          sortField: "RazonSocial",
          align: "CENTER",
          width: "4X"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "",
          value: #"SYSTEM_SYSRULES_recordActionField_v1"(
            actions: {
              #"SYSTEM_SYSRULES_recordActionItem"(
                action: #"urn:appian:record-action:v1:0929493f-cd4a-4d2a-ac93-485c458c24e5/0c2354e9-541b-4aea-9957-3c93432c9e0e",
                identifier: a!defaultValue(fv!row.RazonSocial, "–")
              )
            },
            style: "LINKS",
            display: "LABEL_AND_ICON"
          ),
          align: "CENTER",
          width: "1X"
        )
      },
      validations: {},
      shadeAlternateRows: true
    )
  }
)
